  if(/(?:pikachu|\u30d4\u30ab\u30c1\u30e5\u30a6|\u76ae\u5361\u4e18|\ud53c\uce74\uce04)/i.test(x)){add(characters,"Pikachu");add(franchises,"Pokemon");}
