async function sha256Hex(value=""){
  const data=new TextEncoder().encode(String(value));const digest=await crypto.subtle.digest("SHA-256",data);return [...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,"0")).join("");
}

async function logEvent(env,eventType,detail={}){
  if(!env.SUPABASE_URL||!env.SUPABASE_SECRET_KEY)return false;
  try{
    // v3.7.35 — reserve metadata.version exclusively for the Worker/app version.
    // Older x402 telemetry used metadata.version=2 for the protocol version,
    // which overwrote the app version and caused current-version KPI filtering
    // to silently exclude valid x402_gate_entered/payment_required/paid events.
    const incomingMetadata={...(detail.metadata||{})};
    if(incomingMetadata.protocol==="x402"&&incomingMetadata.version!=null&&incomingMetadata.x402_version==null){
      incomingMetadata.x402_version=incomingMetadata.version;
    }
    delete incomingMetadata.version;
    const metadata={...incomingMetadata,version:VERSION};
    await sb(env,"/api_events",{method:"POST",headers:{Prefer:"return=minimal"},body:JSON.stringify({occurred_at:new Date().toISOString(),event_type:eventType,endpoint:detail.endpoint||null,product_id:detail.product_id?String(detail.product_id):null,payer_hash:detail.payer_hash||null,amount_atomic:detail.amount_atomic!=null?Number(detail.amount_atomic):null,amount_usdc:detail.amount_usdc!=null?Number(detail.amount_usdc):null,payment_network:detail.payment_network||null,transaction_hash:detail.transaction_hash||null,metadata})});
    return true;
  }catch(e){console.warn("KPI event logging failed",safeError(e));return false;}
}

function getNested(obj,path=[]){let cur=obj;for(const key of path){if(cur==null||typeof cur!=="object")return null;cur=cur[key];}return cur??null;}
function extractPaymentPayer(payload,settlement=null){const candidates=[["payload","authorization","from"],["payload","authorization","payer"],["payload","from"],["authorization","from"],["authorization","payer"],["payer"],["from"],["paymentPayload","payload","authorization","from"],["transaction","payer"],["transaction","from"]];for(const p of candidates){const v=getNested(payload,p)||getNested(settlement,p);if(typeof v==="string"&&v.length>=20)return v;}return null;}
function extractSettlementTx(settlement){for(const p of [["transaction"],["transactionHash"],["txHash"],["tx"],["signature"],["receipt","transactionHash"],["receipt","signature"]]){const v=getNested(settlement,p);if(typeof v==="string"&&v)return v;}return null;}
async function payerHashFromPayment(payload,settlement){const payer=extractPaymentPayer(payload,settlement);return payer?sha256Hex(`anime-intelligence:${payer}`):null;}

function configuredTestPayerHashes(env){
  return new Set(String(env?.X402_TEST_PAYER_HASHES||"").split(",").map(x=>x.trim()).filter(Boolean));
}
// v3.7.92 — isolate known legacy self-tests without permanently blacklisting a generic Node/NL fingerprint.
// The fingerprint below was produced by our own pre-v3.7.92 test runner. It is treated as test traffic only
// for events at or before the final known self-test window. Future traffic with the same coarse fingerprint
// remains eligible to count as external unless it carries an explicit test marker.
const LEGACY_SELF_TEST_FINGERPRINT_CUTOFFS={
  "03ed7b5e9a95f7f08a07af23":"2026-09-24T08:28:51.132Z"
};
function isLegacySelfTestFingerprintEvent(x){
  const fp=String(x?.metadata?.source_fingerprint||"");
  const cutoff=LEGACY_SELF_TEST_FINGERPRINT_CUTOFFS[fp];
  if(!cutoff)return false;
  const ts=Date.parse(String(x?.occurred_at||"")),end=Date.parse(cutoff);
  return Number.isFinite(ts)&&Number.isFinite(end)&&ts<=end;
}
function isAdminE2ETestEvent(x,env){
  const meta=x?.metadata||{},ref=String(meta.referer||"").toLowerCase(),source=String(meta.source_class||"");
  if(source==="admin_or_test"||String(meta.test_mode||"").startsWith("admin_")||String(meta.test_mode||"").startsWith("test_")||ref.includes("/admin")||isLegacySelfTestFingerprintEvent(x))return true;
  const configured=configuredTestPayerHashes(env);
  return !!(x?.payer_hash&&configured.has(String(x.payer_hash)));
}

// v3.7.98 — exact known self-test signature. This is intentionally narrower than a permanent
// fingerprint blacklist: the fingerprint alone is not enough. The UA, country and literal query
// must also match the test runner signature observed in our own historical/admin tests.
const KNOWN_SELF_TEST_SIGNATURES=[{
  fingerprint:"03ed7b5e9a95f7f08a07af23",
  user_agent:"node",
  country:"NL",
  query:"\u521d\u97f3\u30df\u30af"
}];
function isKnownSelfTestSignatureEvent(x){
  const m=x?.metadata||{};
  const fp=String(m.source_fingerprint||"");
  const ua=String(m.user_agent||"").trim().toLowerCase();
  const country=String(m.country||"").trim().toUpperCase();
  const query=String(m.intent_query||m.query_text||"").trim();
  return KNOWN_SELF_TEST_SIGNATURES.some(sig=>fp===sig.fingerprint&&ua===sig.user_agent&&country===sig.country&&query===sig.query);
}

async function kpiApiEventsCount(env){
  try{
    const r=await fetch(sbBase(env)+"/api_events?select=event_type",{headers:sbHeaders(env,{Prefer:"count=planned",Range:"0-0"})});
    const raw=await r.text();
    if(!r.ok)throw new Error(`Supabase api_events count ${r.status}: ${raw.slice(0,600)}`);
    const cr=r.headers.get("content-range")||"";
    const m=cr.match(/\/(\d+)$/);
    return {ok:true,count:m?Number(m[1]):null,error:null};
  }catch(e){return {ok:false,count:null,error:safeError(e)};}
}

async function readKpiEvents(env,funnelTypes){
  const limit=Math.max(1,Number(PIPELINE.kpiEventReadLimit)||5000);
  const filter=encodeURIComponent(`(${funnelTypes.join(",")})`);
  const primaryPath=`/api_events?select=*&event_type=in.${filter}&order=occurred_at.desc&limit=${limit}`;
  let primaryError=null,fallbackError=null;
  try{
    const rows=await sb(env,primaryPath);
    if(Array.isArray(rows)&&rows.length){
      const count=await kpiApiEventsCount(env);
      return {ok:true,rows,read_mode:"filtered_query",primary_error:null,fallback_error:null,api_events_rows_seen:rows.length,table_has_events:true,total_event_count_estimate:count.count,count_error:count.error};
    }
  }catch(e){primaryError=safeError(e);}

  // A filtered query can fail or return an unexpected empty set after schema/query changes.
  // Fall back to a broad recent read and filter in JavaScript so telemetry failure is never disguised as zero traffic.
  try{
    const broad=await sb(env,`/api_events?select=*&order=occurred_at.desc&limit=${limit}`);
    const broadRows=Array.isArray(broad)?broad:[];
    const allowed=new Set(funnelTypes);
    const rows=broadRows.filter(x=>allowed.has(String(x?.event_type||"")));
    const count=await kpiApiEventsCount(env);
    return {ok:true,rows,read_mode:primaryError?"broad_fallback_after_filtered_error":"broad_fallback_after_filtered_empty",primary_error:primaryError,fallback_error:null,api_events_rows_seen:broadRows.length,table_has_events:broadRows.length>0,total_event_count_estimate:count.count,count_error:count.error};
  }catch(e){fallbackError=safeError(e);}

  const count=await kpiApiEventsCount(env);
  return {ok:false,rows:[],read_mode:"unavailable",primary_error:primaryError,fallback_error:fallbackError,api_events_rows_seen:0,table_has_events:count.ok?(Number(count.count||0)>0):null,total_event_count_estimate:count.count,count_error:count.error,error:fallbackError||primaryError||count.error||"unknown telemetry read failure"};
}

function isContextlessSyntheticShoppingCall(x){
  const m=x?.metadata||{};
  if(m.id_present||m.canonical_product_id)return false;
  const q=String(m.intent_query||m.query_text||"").trim();
  if(!q)return false;
  const deictic=/\b(this|that|this exact|this cheap|this figure|this nendoroid|this listing|this prize|this item|the exact figure|the exact nendoroid)\b/i.test(q);
  const genericOnly=/^(what is the real total cost for a buyer in [a-z ]+\??|when does preorder close for this figure\??|buy or wait for this .*figure\??)$/i.test(q);
  const concreteId=/https?:\/\/|\bjan\s*[:#-]?\s*\d{8,14}\b|\b\d{12,14}\b|\b[A-Z0-9_-]{8,}\b/i.test(q);
  return (deictic||genericOnly)&&!concreteId;
}

async function readAffiliateTelemetry(env){
  const limit=5000;
  const filter=encodeURIComponent('(affiliate_link_served,affiliate_click)');
  try{
    const rows=await sb(env,`/api_events?select=*&event_type=in.${filter}&order=occurred_at.desc&limit=${limit}`);
    return {ok:true,rows:Array.isArray(rows)?rows:[],error:null};
  }catch(e){return {ok:false,rows:[],error:safeError(e)};}
}

