/* =========================================================
   MERCHANT INTELLIGENCE v1.0.0
   Seller-side agent commerce layer for PARTS INTELLIGENCE.
   - Merchants publish exact MPN inventory, fulfillment and trust evidence.
   - Ranking is evidence-based; paid placement is not part of the score.
   - Merchant write access uses per-merchant API keys hashed in Supabase.
========================================================= */

async function sha256HexText(v=""){
  const data=new TextEncoder().encode(String(v||""));
  const digest=await crypto.subtle.digest("SHA-256",data);
  return [...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,"0")).join("");
}
function clamp100(v){return Math.max(0,Math.min(100,Math.round(Number(v)||0)));}
function merchantPublicShape(m){
  if(!m)return null;
  return {id:m.id,slug:m.slug,name:m.name,website_url:m.website_url||null,country_code:m.country_code||null,status:m.status||"active",verified:!!m.verified,agent_description:m.agent_description||null,capabilities:m.capabilities||{},last_feed_at:m.last_feed_at||null,updated_at:m.updated_at||null};
}
function merchantOfferShape(o){
  if(!o)return null;
  const meta=o.metadata&&typeof o.metadata==="object"&&!Array.isArray(o.metadata)?o.metadata:{};
  return {id:o.id,merchant_id:o.merchant_id,merchant_sku:o.merchant_sku,part_id:o.part_id||null,manufacturer:o.manufacturer||null,part_number:o.part_number||null,normalized_part_number:o.normalized_part_number||normalizePartNumber(o.part_number||""),title:o.title||null,mpn:o.mpn||o.part_number||null,gtin:o.gtin||null,condition:o.condition||"new",price:o.price!=null?Number(o.price):null,currency:o.currency||null,stock_quantity:o.stock_quantity!=null?Number(o.stock_quantity):null,stock_status:o.stock_status||"unknown",lead_time_days:o.lead_time_days!=null?Number(o.lead_time_days):null,ships_to:Array.isArray(o.ships_to)?o.ships_to:[],shipping_cost:o.shipping_cost!=null?Number(o.shipping_cost):null,product_url:o.product_url||null,checkout_url:o.checkout_url||null,datasheet_url:o.datasheet_url||null,return_policy_url:o.return_policy_url||null,authorized_distributor:!!o.authorized_distributor,authenticity_evidence_url:o.authenticity_evidence_url||null,compatibility_claim:o.compatibility_claim||null,compatibility_evidence_url:o.compatibility_evidence_url||null,active:o.active!==false,source_updated_at:o.source_updated_at||null,observed_at:o.observed_at||null,updated_at:o.updated_at||null,global_fulfillment:{ships_from_country:String(meta.ships_from_country||"").toUpperCase()||null,tax_included:meta.tax_included===true?true:meta.tax_included===false?false:null,duty_included:meta.duty_included===true?true:meta.duty_included===false?false:null,minimum_order_quantity:Number.isFinite(Number(meta.minimum_order_quantity))?Number(meta.minimum_order_quantity):null,price_valid_until:meta.price_valid_until||null,fulfillment_evidence_url:meta.fulfillment_evidence_url||null,last_verified_at:meta.last_verified_at||o.source_updated_at||o.observed_at||null},commercial_terms:{warranty_url:meta.warranty_url||null,return_window_days:Number.isFinite(Number(meta.return_window_days))?Number(meta.return_window_days):null},metadata:meta};
}
function merchantOfferScore(offer,merchant,buyerCountry=""){
  const o=merchantOfferShape(offer),m=merchantPublicShape(merchant)||{};
  let discover=0,trust=0,ready=0,compat=0,fulfill=0;
  const issues=[],improvements=[];
  if(o.manufacturer)discover+=15; else {issues.push("manufacturer_missing");improvements.push("Add the exact manufacturer name.");}
  if(o.part_number&&o.normalized_part_number)discover+=25; else {issues.push("mpn_missing");improvements.push("Add the exact manufacturer part number (MPN).");}
  if(o.merchant_sku)discover+=10;
  if(o.title)discover+=10; else improvements.push("Add a human-readable product title.");
  if(o.product_url)discover+=15; else {issues.push("product_url_missing");improvements.push("Add a stable product URL that an agent can hand off to.");}
  if(o.gtin)discover+=10; else improvements.push("Add GTIN/JAN/EAN when available.");
  if(o.datasheet_url)discover+=15; else improvements.push("Link the official datasheet or manufacturer document.");

  if(m.verified)trust+=30; else {issues.push("merchant_not_verified");improvements.push("Complete merchant verification.");}
  if(o.authorized_distributor){
    if(m.verified||o.authenticity_evidence_url)trust+=25;
    else {trust+=5;issues.push("authorized_status_unsubstantiated");improvements.push("Substantiate authorized-distributor status with merchant verification or supply-chain evidence.");}
  }else improvements.push("Declare authorized-distributor status only when it can be substantiated.");
  if(o.datasheet_url)trust+=15;
  if(o.authenticity_evidence_url)trust+=10; else improvements.push("Provide authenticity or supply-chain evidence when relevant.");
  if(o.return_policy_url)trust+=10; else {issues.push("return_policy_missing");improvements.push("Publish a machine-readable or stable return-policy URL.");}
  if(m.website_url)trust+=10;

  if(o.price!=null&&o.price>=0)ready+=25; else {issues.push("price_missing");improvements.push("Publish current price.");}
  if(o.currency)ready+=10; else improvements.push("Publish currency with price.");
  if(o.stock_status&&o.stock_status!=="unknown")ready+=20; else {issues.push("stock_unknown");improvements.push("Publish current stock status.");}
  if(o.stock_quantity!=null)ready+=10; else improvements.push("Publish stock quantity when operationally possible.");
  if(o.lead_time_days!=null)ready+=15; else {issues.push("lead_time_missing");improvements.push("Publish lead time in days.");}
  if(o.checkout_url||o.product_url)ready+=10;
  if(Array.isArray(o.ships_to)&&o.ships_to.length)ready+=10; else {issues.push("shipping_regions_missing");improvements.push("Publish ship-to country/region coverage.");}

  if(["in_stock","low_stock"].includes(o.stock_status))fulfill+=30;
  else if(o.stock_status==="backorder"||o.stock_status==="preorder")fulfill+=10;
  if(o.stock_quantity!=null&&o.stock_quantity>0)fulfill+=15;
  if(o.lead_time_days!=null){if(o.lead_time_days<=1)fulfill+=25;else if(o.lead_time_days<=3)fulfill+=20;else if(o.lead_time_days<=7)fulfill+=10;}
  const ships=(o.ships_to||[]).map(x=>String(x).toUpperCase());
  if(ships.length){if(!buyerCountry||ships.includes(String(buyerCountry).toUpperCase())||ships.includes("WORLDWIDE")||ships.includes("ALL"))fulfill+=20;}
  if(o.shipping_cost!=null)fulfill+=10;

  if(o.part_number&&o.mpn&&normalizePartNumber(o.part_number)===normalizePartNumber(o.mpn))compat+=40;
  if(o.datasheet_url)compat+=25;
  if(o.compatibility_evidence_url)compat+=25;
  if(o.compatibility_claim){
    if(o.compatibility_evidence_url)compat+=10;
    else {issues.push("compatibility_claim_without_evidence");improvements.push("A compatibility/substitution claim receives no ranking credit until an official evidence URL is supplied.");}
  }else if(!o.compatibility_evidence_url){
    improvements.push("If claiming substitution/compatibility, provide the official evidence URL.");
  }

  discover=clamp100(discover);trust=clamp100(trust);ready=clamp100(ready);compat=clamp100(compat);fulfill=clamp100(fulfill);
  const overall=clamp100(discover*.25+trust*.25+ready*.25+fulfill*.15+compat*.10);
  const band=overall>=85?"agent_ready":overall>=70?"competitive":overall>=50?"needs_improvement":"low_visibility";
  return {agent_discoverability_score:discover,agent_trust_score:trust,purchase_readiness_score:ready,compatibility_evidence_score:compat,fulfillment_score:fulfill,overall_agent_score:overall,rankability_band:band,issues:[...new Set(issues)],improvements:[...new Set(improvements)].slice(0,12),ranking_policy:"evidence_based_no_paid_placement"};
}
async function merchantByApiKey(env,request){
  const key=String(request.headers.get("x-merchant-key")||"").trim();
  if(!key)return null;
  const hash=await sha256HexText(key);
  const rows=await sbOptional(env,`/merchants?select=*&merchant_api_key_hash=eq.${encodeURIComponent(hash)}&status=eq.active&limit=1`);
  return Array.isArray(rows)&&rows.length?rows[0]:null;
}
async function registerMerchantAdmin(env,body,origin){
  const name=String(body?.name||"").trim();if(!name)throw new Error("merchant_name_required");
  const rawSlug=String(body?.slug||"").trim().toLowerCase().replace(/[^a-z0-9-]+/g,"-").replace(/^-+|-+$/g,"");
  const slug=rawSlug||`merchant-${crypto.randomUUID().slice(0,8)}`;
  const existing=await sbOptional(env,`/merchants?select=id,slug,name,status&slug=eq.${encodeURIComponent(slug)}&limit=1`);
  if(Array.isArray(existing)&&existing.length)throw new Error("merchant_slug_already_exists");
  const apiKey=`mai_${crypto.randomUUID().replace(/-/g,"")}${crypto.randomUUID().replace(/-/g,"").slice(0,16)}`;
  const hash=await sha256HexText(apiKey),now=new Date().toISOString();
  const row={id:crypto.randomUUID(),slug,name,website_url:body?.website_url||null,country_code:String(body?.country_code||"JP").toUpperCase(),status:"active",verified:!!body?.verified,merchant_api_key_hash:hash,merchant_api_key_prefix:apiKey.slice(0,12),agent_description:body?.agent_description||null,capabilities:body?.capabilities||{},metadata:body?.metadata||{},created_at:now,updated_at:now};
  const saved=await sb(env,"/merchants",{method:"POST",headers:{Prefer:"return=representation"},body:JSON.stringify(row)});
  const merchant=Array.isArray(saved)&&saved.length?saved[0]:row;
  await sbOptional(env,"/merchant_agent_profiles?on_conflict=merchant_id",{method:"POST",headers:{Prefer:"resolution=merge-duplicates,return=minimal"},body:JSON.stringify({merchant_id:merchant.id,discovery_name:name,description:body?.agent_description||`${name} machine-readable commerce profile`,checkout_mode:"link_out",supports_agent_checkout:false,protocols:["https","json"],capabilities:body?.capabilities||{},policies:{ranking:"evidence_based_no_paid_placement"},metadata:{feed_url:`${origin}/v1/merchant/feed?merchant=${encodeURIComponent(slug)}`},updated_at:now})});
  return {ok:true,service:"MERCHANT INTELLIGENCE",version:VERSION,merchant:merchantPublicShape(merchant),merchant_api_key:apiKey,important:"This API key is returned once. Store it securely. Send it in x-merchant-key for merchant write endpoints.",feed_url:`${origin}/v1/merchant/feed?merchant=${encodeURIComponent(slug)}`,diagnostic_url:`${origin}/v1/merchant/diagnostic?merchant=${encodeURIComponent(slug)}`};
}

function safeMerchantUrl(v){
  const s=String(v||"").trim();if(!s)return null;
  try{const u=new URL(s);if(!["http:","https:"].includes(u.protocol))return null;return u.toString();}catch{return null;}
}
async function merchantRegistrationIpHash(request){
  const raw=String(request?.headers?.get("cf-connecting-ip")||request?.headers?.get("x-forwarded-for")||"").split(",")[0].trim();
  return raw?await sha256HexText(`merchant-registration-v1|${raw}`):null;
}
async function enforceMerchantRegistrationRateLimit(env,request){
  const ipHash=await merchantRegistrationIpHash(request);
  if(!ipHash)return {ip_hash:null,recent_count:null};
  const cutoff=new Date(Date.now()-24*60*60*1000).toISOString();
  const path=`/merchants?select=id&metadata-%3E%3Eregistration_ip_hash=eq.${encodeURIComponent(ipHash)}&created_at=gte.${encodeURIComponent(cutoff)}&limit=4`;
  const rows=await sbOptional(env,path);
  const count=Array.isArray(rows)?rows.length:0;
  if(count>=3){
    const e=new Error("merchant_registration_rate_limited");
    e.status=429;
    throw e;
  }
  return {ip_hash:ipHash,recent_count:count};
}
function publicMerchantRegistrationBody(body){
  const name=String(body?.name||body?.merchant_name||"").trim().slice(0,120);
  if(name.length<2)throw new Error("merchant_name_too_short");
  const country=String(body?.country_code||"JP").trim().toUpperCase();
  if(!/^[A-Z]{2}$/.test(country))throw new Error("invalid_country_code");
  const websiteRaw=String(body?.website_url||"").trim();
  const website=websiteRaw?safeMerchantUrl(websiteRaw):null;
  if(websiteRaw&&!website)throw new Error("invalid_website_url");
  const slugRaw=String(body?.slug||"").trim().toLowerCase();
  if(slugRaw&&!/^[a-z0-9][a-z0-9-]{1,62}[a-z0-9]$/.test(slugRaw))throw new Error("invalid_slug");
  return {
    name,
    slug:slugRaw||"",
    website_url:website,
    country_code:country,
    verified:false,
    agent_description:String(body?.agent_description||"").trim().slice(0,1000)||null,
    capabilities:body?.capabilities&&typeof body.capabilities==="object"&&!Array.isArray(body.capabilities)?body.capabilities:{},
    metadata:{
      onboarding_source:"public_self_service",
      merchant_type:String(body?.merchant_type||"").trim().slice(0,80)||null,
      direct_seller:body?.direct_seller===true,
      registration_terms_accepted:body?.accept_terms===true,
      registered_at:new Date().toISOString()
    }
  };
}
async function registerMerchantPublic(env,request,body,origin){
  if(body?.company_fax)return {ok:true,service:"MERCHANT INTELLIGENCE",version:VERSION,registration:"accepted"};
  if(body?.accept_terms!==true)throw new Error("terms_acceptance_required");
  const rate=await enforceMerchantRegistrationRateLimit(env,request);
  const normalized=publicMerchantRegistrationBody(body);
  normalized.metadata={...(normalized.metadata||{}),registration_ip_hash:rate.ip_hash||null};
  return registerMerchantAdmin(env,normalized,origin);
}
async function merchantSelfApi(env,request,origin){
  const merchant=await merchantByApiKey(env,request);
  if(!merchant)return {ok:false,status:401,error:"invalid_merchant_key"};
  const profiles=await sbOptional(env,`/merchant_agent_profiles?select=*&merchant_id=eq.${encodeURIComponent(merchant.id)}&limit=1`);
  const countRows=await sbOptional(env,`/merchant_offers?select=id&merchant_id=eq.${encodeURIComponent(merchant.id)}&active=eq.true&limit=1000`);
  return {
    ok:true,service:"MERCHANT INTELLIGENCE",version:VERSION,
    merchant:merchantPublicShape(merchant),
    agent_profile:Array.isArray(profiles)&&profiles.length?profiles[0]:null,
    active_offer_count:Array.isArray(countRows)?countRows.length:null,
    endpoints:{
      feed:`${origin}/v1/merchant/feed?merchant=${encodeURIComponent(merchant.slug)}`,
      diagnostic:`${origin}/v1/merchant/diagnostic?merchant=${encodeURIComponent(merchant.slug)}`,
      search:`${origin}/v1/merchant/search?part_number=<MPN>&manufacturer=<MANUFACTURER>`
    }
  };
}
async function rotateMerchantApiKey(env,request){
  const merchant=await merchantByApiKey(env,request);
  if(!merchant)return {ok:false,status:401,error:"invalid_merchant_key"};
  const apiKey=`mai_${crypto.randomUUID().replace(/-/g,"")}${crypto.randomUUID().replace(/-/g,"").slice(0,16)}`;
  const hash=await sha256HexText(apiKey),now=new Date().toISOString();
  await sb(env,`/merchants?id=eq.${encodeURIComponent(merchant.id)}`,{
    method:"PATCH",headers:{Prefer:"return=minimal"},
    body:JSON.stringify({merchant_api_key_hash:hash,merchant_api_key_prefix:apiKey.slice(0,12),updated_at:now})
  });
  return {ok:true,service:"MERCHANT INTELLIGENCE",version:VERSION,merchant:merchantPublicShape({...merchant,updated_at:now}),merchant_api_key:apiKey,important:"The previous merchant API key is now invalid. This new key is returned once; store it securely."};
}
