    const filterDiagnostics={offers_scored:scoredOffers.length,passed_relevance:scoredOffers.filter(o=>o._relevance>=UNIVERSAL_DISCOVERY_POLICY.relevance_floor).length,rejected_relevance:scoredOffers.filter(o=>o._relevance<UNIVERSAL_DISCOVERY_POLICY.relevance_floor).length,score_max:scoredOffers.length?Math.max(...scoredOffers.map(o=>o._relevance)):null,score_top5:scoredOffers.map(o=>o._relevance).sort((a,b)=>b-a).slice(0,5)};
    const snapshotLogged=await logEvent(env,"universal_product_snapshot",{endpoint:"/v1/commerce/search",metadata:{domain,query_text:query,query_key:key,query_family:queryFamily,identity_key:identityKey,identifiers,manufacturer:manufacturer||null,buyer_country:body?.buyer_country||body?.destination?.country||null,offers:snapshot,source_diversity:[...new Set(snapshot.map(x=>x.provider).filter(Boolean))].length,provider_errors:(result?.provider_errors||[]).slice(0,6),observed_at:now,version:VERSION}});

