  const result={attempted:0,identities_with_offer:0,exact_links:0,provider_calls:0,detail_calls:0,offers:[],errors:[]};
  if(!budget||!env.EBAY_CLIENT_ID||!env.EBAY_CLIENT_SECRET)return result;
  let sourceId=null,fxInfo={rate:null,source:"unavailable"},recent=[];
  try{sourceId=(await ensureSource(env,{slug:"ebay",name:"eBay",type:"marketplace",base_url:"https://www.ebay.com/"})).source_id||null;}catch(e){result.errors.push({stage:"source",error:safeError(e)});}
  try{fxInfo=await resolveUsdJpy(env);}catch{}
