    const meta=p?.metadata||{},ids=meta?.identifiers||{},gtin=cleanJan(p?.jan_code||ids?.gtin||""),mpn=String(ids?.mpn||p?.model_number||"").trim(),manufacturer=String(p?.manufacturer||ids?.manufacturer||"").trim();
    if(!gtin&&!mpn)continue;
