  const language=detectLanguage(query,explicitLang,request?.headers?.get("accept-language")||"");
  const manufacturer=inferPurchaseManufacturer(query,product.manufacturer||body?.manufacturer||"");
  const mpn=String(product.mpn||product.part_number||body?.mpn||body?.part_number||body?.manufacturer_part_number||extractLikelyMpn(query)||"").trim()||null;
  const country=inferPurchaseCountry(query,destination.country||body?.buyer_country||body?.country||"");
  const currency=String(requirements.currency||body?.currency||PURCHASE_DEFAULT_CURRENCY[country]||"USD").toUpperCase();
  const quantity=Math.max(1,Math.min(10000,Math.floor(purchaseFinite(body?.quantity??requirements.quantity)??1)));
  const maxTotal=purchaseFinite(requirements.max_total_cost??body?.max_total_cost??body?.budget);
  const deadline=inferPurchaseDeadline(query,requirements.delivery_deadline||body?.delivery_deadline||body?.deadline||"");
