function purchaseDecisionBodyFromUrl(url){
  const b={};
  for(const k of ["query","need","intent","language","lang","domain","vertical","category","manufacturer","mpn","part_number","gtin","buyer_country","country","postal_code","currency","delivery_deadline","deadline","canonical_product_id","fitment_evidence","required_voltage","size","condition"]){
    const v=url.searchParams.get(k);if(v!==null&&v!=="")b[k]=v;
  }
  for(const k of ["quantity","max_total_cost","budget"]){const v=url.searchParams.get(k);if(v!==null&&v!=="")b[k]=Number(v);}
  for(const k of ["authorized_only","authenticity_required","substitutes_allowed","returns_required","warranty_required","regulatory_required"]){const v=url.searchParams.get(k);if(v!==null)b[k]=/^(1|true|yes)$/i.test(v);}
  return b;
}

async function universalPurchaseDecisionApi(request,env,origin,ctx=null){
  const hasPaymentHeader=!!(request.headers.get("payment-signature")||request.headers.get("x-payment"));
  let body={};
  if(request.method==="GET"){
    body=purchaseDecisionBodyFromUrl(new URL(request.url));
  }else{
    try{body=await request.json();}catch{
      if(hasPaymentHeader)return json({ok:false,service:"AI PURCHASE INTELLIGENCE",version:VERSION,error:"invalid_json",charged:false},400);
      return x402Gate(request,env,PRICES.purchaseDecision,"Global multilingual purchase decision: resolve product identity, evidence, merchant offers, known landed cost and best purchase route",async()=>{throw new Error("purchase_body_required");},ctx);
    }
  }
  const intent=normalizePurchaseDecisionIntent(body,request);
  if(intent.original_query&&!hasPaymentHeader){
    deferTelemetry(ctx,logEvent(env,"universal_product_demand",{endpoint:"/v1/purchase-decision",metadata:{domain:intent.domain,query_text:String(intent.original_query).slice(0,180),query_key:universalQueryKey(intent.domain,intent.original_query),query_family:universalQueryFamily(intent.domain,intent.original_query),language:intent.language,buyer_country:intent.destination.country,pre_payment:true,attribution_key:purchaseAttributionKey(intent),version:VERSION}}));
  }
  if(!intent.original_query&&!intent.product.mpn&&!intent.product.canonical_product_id){
    if(!hasPaymentHeader)return x402Gate(request,env,PRICES.purchaseDecision,"Global multilingual purchase decision: resolve product identity, evidence, merchant offers, known landed cost and best purchase route",async()=>{throw new Error("purchase_query_or_product_required");},ctx);
    return json({ok:false,service:"AI PURCHASE INTELLIGENCE",version:VERSION,error:"purchase_query_or_product_required",charged:false,normalized_intent:intent},400);
  }
  // Preserve the existing pre-payment identity principle: unresolved exact products are rejected before settlement.
  if(intent.domain==="parts"){
    const resolved=await resolvePart(env,{query:intent.original_query||"",part_number:intent.product.mpn||"",manufacturer:intent.product.manufacturer||""});
    if(!resolved.ok)return json({ok:false,service:"AI PURCHASE INTELLIGENCE",version:VERSION,error:"part_not_resolved",charged:false,normalized_intent:intent,resolution:resolved},resolved.status||404,{"cache-control":"no-store"});
  }else if(intent.domain==="anime_collectibles"){
    const u=new URL(`${origin}/v1/full-intelligence`);
    if(intent.product.canonical_product_id)u.searchParams.set("id",intent.product.canonical_product_id);else u.searchParams.set("query",intent.original_query||"");
    u.searchParams.set("buyer_country",intent.destination.country);u.searchParams.set("lang",intent.language);
    const preflight=await preflightPaidProduct(env,u);
    if(!preflight.ok)return json({ok:false,service:"AI PURCHASE INTELLIGENCE",version:VERSION,error:"collectible_not_resolved",charged:false,normalized_intent:intent,resolution:preflight.body},preflight.status||404,{"cache-control":"no-store"});
  }
  return x402Gate(request,env,PRICES.purchaseDecision,"Global multilingual purchase decision: resolve product identity, evidence, merchant offers, known landed cost and best purchase route",async()=>{
    const out=await buildUniversalPurchaseDecision(request,env,body,origin);
    if(out?.status&&out.status>=400){const e=new Error(out.error||"purchase_decision_failed");e.public_payload=out;throw e;}
    deferTelemetry(ctx,logRequestStage(env,request,"universal_purchase_decision_served",{metadata:{domain:out?.domain||intent.domain,query_family:universalQueryFamily(intent.domain,intent.original_query||intent.product.mpn||""),attribution_key:purchaseAttributionKey(intent),language:intent.language,destination_country:intent.destination.country,can_purchase:!!out?.decision?.can_purchase,decision_action:out?.decision?.action||null,reason_codes:Array.isArray(out?.decision?.reason_codes)?out.decision.reason_codes.slice(0,12):[],cross_provider_corroborated_offers:Number(out?.cross_provider_corroborated_offers||out?.persistence?.cross_provider_corroborated_candidates||0)}}));
    return {...out,_payment_attribution:{domain:out?.domain||intent.domain,query_family:universalQueryFamily(intent.domain,intent.original_query||intent.product.mpn||""),attribution_key:purchaseAttributionKey(intent),decision_action:out?.decision?.action||null,can_purchase:!!out?.decision?.can_purchase},price_usdc_atomic:PRICES.purchaseDecision,price_usdc:Number(PRICES.purchaseDecision)/1000000};
  },ctx);
}

function shapePaidResponse(path,intel){
  const base={language:intel.language,generated_at:intel.generated_at};
  if(path==="/v1/identify")return {...base,product:intel.product,provenance:intel.provenance};
  if(path==="/v1/market")return {...base,product:compactProductResponse(intel.product),market:intel.market,freshness:intel.freshness,routing:intel.routing};
  if(path==="/v1/rarity")return {...base,product:compactProductResponse(intel.product),rarity:intel.rarity,rerelease:intel.product.rerelease,rerelease_generation:intel.product.rerelease_generation};
  if(path==="/v1/authenticity")return {...base,product:compactProductResponse(intel.product),authenticity_risk:intel.authenticity_risk};
  if(path==="/v1/buy-wait")return {...base,product:compactProductResponse(intel.product),buy_wait:intel.buy_wait,market_snapshot:{lowest_price_jpy:intel.market.lowest_price_jpy,median_price_jpy:intel.market.median_price_jpy,msrp_jpy:intel.market.msrp_jpy},rarity:intel.rarity,routing:intel.routing};
  if(path==="/v1/best-place")return {...base,product:compactProductResponse(intel.product),best_place:intel.best_place,routing:intel.routing};
  if(path==="/v1/listing-match")return {...base,product:compactProductResponse(intel.product),listing_match:intel.listing_match};
  if(path==="/v1/deadline")return {...base,product:compactProductResponse(intel.product),deadline:intel.deadline};
  if(path==="/v1/landed-cost")return {...base,product:compactProductResponse(intel.product),landed_cost:intel.landed_cost,best_place:intel.best_place,routing:intel.routing};
  if(path==="/v1/price-history")return {...base,product:compactProductResponse(intel.product),price_history:intel.price_history,market_snapshot:{lowest_price_jpy:intel.market.lowest_price_jpy,median_price_jpy:intel.market.median_price_jpy,highest_price_jpy:intel.market.highest_price_jpy,msrp_jpy:intel.market.msrp_jpy},freshness:intel.freshness};
  if(path==="/v1/shopping-intelligence")return shoppingIntelligenceView(intel,"https://anime-intelligence.goodmy0312.workers.dev");
  return intel;
}

