  return {ok:systemReady,service:PLATFORM_NAME,version:VERSION,build_id:BUILD_ID,readiness:systemReady?(warnings.length?"OPERATIONAL_WITH_WARNINGS":"PRODUCTION_READY"):"BLOCKED",blockers,warnings,metric_scope:useCurrent?"current_version":"rolling_24h",signals:{embedded_v3_runs_24h:v3runs,embedded_candidates_inserted_24h:Number(g?.parts_growth?.embedded_candidates_inserted_24h||0),generic_market_snapshots_24h:Number(g?.generic_growth?.market_snapshots_24h||0),discovery_unique_yield:uy??null,gtin_yield:useCurrent?cv.gtin_yield:g?.generic_growth?.gtin_yield_24h??null,canonical_promotion_yield:cy??null,merchant_evidence_yield:my??null,merchant_trust_yield:mty??null,purchase_ready_yield:py??null,decision_ready_yield:dy??null,canonical_decision_ready_yield:cdy??null,cross_provider_corroborated_candidates:useCurrent?cv.cross_provider_corroborated_candidates:g?.generic_growth?.cross_provider_corroborated_candidates_24h??null,canonical_per_provider_call:useCurrent?cv.canonical_per_provider_call:g?.generic_growth?.canonical_per_provider_call_24h??null,canonical_quarantined:useCurrent?cv.canonical_quarantined:g?.generic_growth?.canonical_quarantined_24h??null,brands_covered:useCurrent?cv.brands_covered:Number(g?.generic_growth?.brands_covered_24h||0),merchant_due_queue_backlog:due,purchase_ready_offers_sample:Number(g?.database?.purchase_ready_offers_sample||0),verified_merchants_sample:Number(g?.database?.verified_merchants_sample||0),external_paid_calls:Number(r?.external_paid_calls||0),external_revenue_usdc:Number(r?.external_revenue_usdc||0)},external_dependencies_note:"External merchant anti-bot controls, Cloudflare/Supabase availability and buyer demand cannot be guaranteed by Worker code.",generated_at:new Date().toISOString()};
