async function seedQueue(env){
  const backlog=await activeQueueBacklog(env,DAILY_SEED_PAUSE_THRESHOLD+1);
  if(backlog!=null&&backlog>=DAILY_SEED_PAUSE_THRESHOLD)return {ok:true,seeded:0,skipped:true,reason:"daily_seed_queue_guard",active_backlog_probe:backlog};
  const rows=[];
  for(const s of ALL_SOURCES.filter(x=>x.kind!=="merchant_offer"||x.collection_enabled!==false))for(const u of [...s.seeds,...(s.bootstrapSeeds||[])])rows.push({id:crypto.randomUUID(),source_slug:s.slug,url:u,status:"pending",depth:0,attempts:0,next_attempt_at:new Date().toISOString(),created_at:new Date().toISOString(),updated_at:new Date().toISOString()});
  await sb(env,"/parts_collector_queue?on_conflict=source_slug,url",{method:"POST",headers:{Prefer:"resolution=ignore-duplicates,return=minimal"},body:JSON.stringify(rows)});
  return {ok:true,seeded:rows.length,active_backlog_probe:backlog};
}

async function seedDynamicMerchantQueries(env,preferredManufacturers=[]){
  const globalBacklog=await activeQueueBacklog(env,HARD_QUEUE_CEILING+1);
  const merchantBacklog=await activeMerchantQueueBacklog(env,MERCHANT_QUEUE_HARD_CEILING+1);
  if(globalBacklog!=null&&globalBacklog>=HARD_QUEUE_CEILING)return {parts_sampled:0,queries_seeded:0,paused:true,reason:"global_hard_queue_ceiling",active_backlog_probe:globalBacklog,merchant_backlog_probe:merchantBacklog};
  if(merchantBacklog!=null&&merchantBacklog>=MERCHANT_QUEUE_HARD_CEILING)return {parts_sampled:0,queries_seeded:0,paused:true,reason:"merchant_hard_queue_ceiling",active_backlog_probe:globalBacklog,merchant_backlog_probe:merchantBacklog,soft_budget:MERCHANT_QUEUE_BUDGET,hard_ceiling:MERCHANT_QUEUE_HARD_CEILING};
  const trickleMode=merchantBacklog!=null&&merchantBacklog>=MERCHANT_QUEUE_BUDGET;
  const targetParts=trickleMode?1:4;
  const tick=Math.floor(Date.now()/600000);
  const preferred=[...new Set((preferredManufacturers||[]).filter(x=>universeProfile(x)))];
  const parts=[];
  const attemptedManufacturers=[];
  for(const manufacturer of preferred.slice(0,4)){
    attemptedManufacturers.push(manufacturer);
    const rows=await sbOptional(env,`/parts_catalog?select=manufacturer,part_number,normalized_part_number,lifecycle_status,source_confidence&manufacturer=eq.${encodeURIComponent(manufacturer)}&lifecycle_status=neq.discontinued&order=updated_at.desc&limit=1`);
    if(Array.isArray(rows)&&rows[0]&&!parts.some(p=>p.manufacturer===rows[0].manufacturer))parts.push(rows[0]);
    if(parts.length>=targetParts)break;
  }
  if(parts.length<targetParts){
    const fallback=await sbOptional(env,"/parts_catalog?select=manufacturer,part_number,normalized_part_number,lifecycle_status,source_confidence&manufacturer=neq.OMRON&lifecycle_status=neq.discontinued&order=source_confidence.desc,updated_at.desc&limit=40");
    const rotated=rotateWindow(Array.isArray(fallback)?fallback:[],tick,24);
    for(const row of rotated){
      if(!row?.manufacturer||!row?.part_number||!universeProfile(row.manufacturer))continue;
      if(!OFFER_SOURCES.some(x=>x.collection_enabled!==false&&x.manufacturer===row.manufacturer))continue;
      if(parts.some(p=>p.manufacturer===row.manufacturer))continue;
      parts.push(row);
      if(parts.length>=targetParts)break;
    }
  }
  const rows=[];const now=new Date().toISOString();
  for(const part of parts){
    if(!part?.manufacturer||!part?.part_number)continue;
    const profile=universeProfile(part.manufacturer);
    const domains=(profile?.domains||[]).join(" ").toLowerCase();
    const electronic=/(semiconductor|mcu|soc|sensor|connector|power|sic|mosfet|igbt|imu|radar|lidar|connectivity|passive)/.test(domains);
    const mechanical=/(motor|bearing|reducer|linear|actuator|servo|gear|motion)/.test(domains);
    const preferredSlugs=electronic&&!mechanical?["digikey-japan","mouser","monotaro-japan"]:mechanical&&!electronic?["misumi-japan","monotaro-japan","digikey-japan"]:["digikey-japan","mouser","misumi-japan","monotaro-japan"];
    const sources=OFFER_SOURCES.filter(x=>x.collection_enabled!==false&&x.manufacturer===part.manufacturer&&preferredSlugs.includes(x.merchant_slug)).sort((a,b)=>preferredSlugs.indexOf(a.merchant_slug)-preferredSlugs.indexOf(b.merchant_slug)).slice(0,trickleMode?1:3);
    for(const source of sources){
      const url=merchantSearchUrl(source,part.part_number);if(!url)continue;
      rows.push({id:crypto.randomUUID(),source_slug:source.slug,url,status:"pending",depth:0,attempts:0,next_attempt_at:now,created_at:now,updated_at:now});
    }
  }
  const seedRows=trickleMode?rows.slice(0,MERCHANT_TRICKLE_SEED_MAX_ROWS):rows;
  if(seedRows.length)await sbOptional(env,"/parts_collector_queue?on_conflict=source_slug,url",{method:"POST",headers:{Prefer:"resolution=ignore-duplicates,return=minimal"},body:JSON.stringify(seedRows)});
  return {parts_sampled:parts.length,queries_seeded:seedRows.length,paused:false,mode:trickleMode?"drain_priority_trickle_seed":"normal",seeding_limited:trickleMode,soft_budget:MERCHANT_QUEUE_BUDGET,hard_ceiling:MERCHANT_QUEUE_HARD_CEILING,active_backlog_probe:globalBacklog,merchant_backlog_probe:merchantBacklog,preferred_manufacturers:preferred.slice(0,4),seeded_manufacturers:[...new Set(parts.map(x=>x.manufacturer))],seeded_source_slugs:[...new Set(seedRows.map(x=>x.source_slug))],fallback_used:parts.some(x=>!preferred.includes(x.manufacturer))};
}
