  const preflight=await collectorDbPreflight(env);
  if(!preflight.ok){
    return {ok:false,service:SERVICE,version:VERSION,build_id:BUILD_ID,trigger:"collector_run",started_at:nowIso,finished_at:new Date().toISOString(),mode:"database_unavailable",selected_rows:0,processed:[],errors:[{stage:"db_preflight",error:preflight.error}],database_preflight:preflight};
  }
