  // v7: saturated Merchant queue becomes a bounded drain priority instead of a permanent seeding pause.
  const forceMerchantDrain=merchantBacklogAtStart!=null&&merchantBacklogAtStart>=MERCHANT_QUEUE_BUDGET;
  const mode=forceMerchantDrain?"offer":((tick%6===0||tick%6===3)?"offer":((tick%6===2||tick%6===5)?"manufacturer_watch":"catalog"));
  const offerSlot=mode==="offer",watchSlot=mode==="manufacturer_watch";
  const requested=Math.max(1,Math.min(2,Number(limit)||MAX_PAGES_PER_RUN));
