  const latestRun=(Array.isArray(runs)&&runs.length?runs[0]:null)||(Array.isArray(probe.data)&&probe.data.length?probe.data[0]:null);const latestTs=latestRun?.finished_at||latestRun?.started_at||null;const latestAgeMinutes=latestTs?Math.max(0,Math.round((Date.now()-new Date(latestTs).getTime())/60000)):null;
  const recent=Array.isArray(runs)?runs:[];const recentVersion=recent.filter(x=>x.version===`collector-${VERSION}`);
