  const diagnosticsReachable=checks.every(x=>x.ok),samplesComplete=checks.every(x=>x.sample_ok),dbReachable=probe.ok,selftest=collectorSelfTest();
  const activeOffers=Array.isArray(merchantOffers)?merchantOffers.filter(x=>x.active===true):[];
  const nonOmronActive=activeOffers.filter(x=>x.manufacturer&&x.manufacturer!=="OMRON");
  const recentTotals=recentVersion.reduce((a,r)=>{const m=r?.metadata||{};for(const k of ["canonical_exact_found","canonical_catalog_found","canonical_candidates_skipped","canonical_parts_upserted","engineering_metrics_found","engineering_metrics_saved","deep_links_enqueued","merchant_detail_links_promoted","relation_hints_saved","merchant_offers_upserted"])a[k]+=Number(m[k]||0);return a;},{canonical_exact_found:0,canonical_catalog_found:0,canonical_candidates_skipped:0,canonical_parts_upserted:0,engineering_metrics_found:0,engineering_metrics_saved:0,deep_links_enqueued:0,merchant_detail_links_promoted:0,relation_hints_saved:0,merchant_offers_upserted:0});
