async function embeddedPartsCollectorNeedsRun(env,nowMs=Date.now()){
  if(!env?.SUPABASE_URL||!env?.SUPABASE_SECRET_KEY)return false;
  try{
    // v7 ownership rule: only a recent embedded v3 run owns the lease.
    // Legacy collector-2.x heartbeats must never suppress the authoritative embedded collector.
    const since=new Date(nowMs-8*60*1000).toISOString();
    const rows=await sb(env,`/parts_ingest_runs?select=finished_at,version&finished_at=gte.${encodeURIComponent(since)}&version=eq.collector-3.0.0&limit=2`);
    return !(Array.isArray(rows)&&rows.some(r=>String(r?.version||"")==="collector-3.0.0"));
  }catch{return true;}
}
async function runEmbeddedPartsCollectorFailover(event,env){
  const pending=[];
  const fakeCtx={waitUntil(p){pending.push(Promise.resolve(p));}};
  await EMBEDDED_PARTS_COLLECTOR.scheduled(event,env,fakeCtx);
  const settled=await Promise.allSettled(pending);
  const rejected=settled.filter(x=>x.status==="rejected").map(x=>safeError(x.reason));
  return {ok:rejected.length===0,mode:"embedded_failover",tasks:pending.length,rejected};
}
async function embeddedCollectorFetch(request,env,ctx){
  const u=new URL(request.url);
  u.pathname=u.pathname.replace(/^\/collector/,"")||"/";
  const req=new Request(u.toString(),request);
  return EMBEDDED_PARTS_COLLECTOR.fetch(req,env,ctx);
}

// v7.1 deterministic cron contract. Works with either */1 or */10 Cloudflare triggers.
// Only UTC minutes divisible by 10 perform network-heavy scheduled work.
// 00/20/40 = embedded Parts Collector v3; 10 = universal rotation;
// 30 = catalog enrichment; 50 = universal demand refresh.
function scheduledTaskForTime(timeMs){
  // All ten-minute slots are productive. This avoids relying on :40/:50 cron configuration.
  const d=new Date(Number(timeMs||Date.now()));
  const m=d.getUTCMinutes();
  if(m%10!==0)return "discovery_recovery"; // also works with an unusual single-minute cron
  if(m===0||m===20)return "parts_collector_v3";
  if(m===10)return "rotation";
  if(m===30)return "catalog_enrichment";
  if(m===40)return "universal_discovery";
  if(m===50)return "universal_discovery";
  return "discovery_recovery";
}

async function universalDiscoveryLeaseStatus(env,nowMs=Date.now(),freshMinutes=55){
  const now=Number(nowMs||Date.now());
  const rows=await sbOptional(env,`/api_events?select=occurred_at,metadata&event_type=eq.universal_expansion_run&order=occurred_at.desc&limit=1`);
  const last=Array.isArray(rows)&&rows.length?rows[0]:null;
  const lastMs=last?.occurred_at?Date.parse(last.occurred_at):0;
  const ageMinutes=lastMs?Math.max(0,(now-lastMs)/60000):null;
  const fresh=ageMinutes!=null&&ageMinutes<Math.max(1,Number(freshMinutes)||55);
  return {due:!fresh,last_run_at:last?.occurred_at||null,age_minutes:ageMinutes,fresh_minutes:freshMinutes};
}

