async function universalSupabaseProbe(env,timeoutMs=5000){
  if(!env?.SUPABASE_URL||!env?.SUPABASE_SECRET_KEY)return {ok:false,error:"supabase_not_configured",latency_ms:0};
  const started=Date.now();const c=new AbortController();const t=setTimeout(()=>c.abort("timeout"),timeoutMs);
  try{
    const r=await fetch(String(env.SUPABASE_URL).replace(/\/$/,"")+"/rest/v1/products?select=id&limit=1",{method:"GET",headers:{apikey:env.SUPABASE_SECRET_KEY,Authorization:`Bearer ${env.SUPABASE_SECRET_KEY}`,Accept:"application/json"},signal:c.signal});
    const raw=await r.text();if(!r.ok)throw new Error(`Supabase ${r.status}: ${raw.slice(0,300)}`);
    let data=[];try{data=raw?JSON.parse(raw):[];}catch{}
    return {ok:true,has_product:Array.isArray(data)&&data.length>0,latency_ms:Date.now()-started};
  }catch(e){return {ok:false,error:e?.name==="AbortError"?"supabase_probe_timeout":safeError(e),latency_ms:Date.now()-started};}
  finally{clearTimeout(t);}
}

